// سوالات benchmark به‌صورت درون‌خطی (تغییرشون همینجا کافیه، فایل جدا لازم نیست)
const QUESTIONS = [
  {
    "id": "filter_001",
    "question": "کدام محصولات قرمز هستند و در حال حاضر به‌عنوان کالای نهایی (Finished Goods) علامت‌گذاری شده‌اند؟",
    "category": "filter",
    "difficulty": "easy",
    "gold_sql": "SELECT ProductKey, EnglishProductName FROM dbo.DimProduct WHERE Color = N'Red' AND FinishedGoodsFlag = 1 ORDER BY EnglishProductName;",
    "score_on": [
      "ProductKey"
    ]
  }
];
return QUESTIONS.map(q => ({ json: q }));

// ===== امتیازدهی هر سوال: مقایسه ردیف‌های مدل با ردیف‌های gold =====
const item = $('Loop Over Questions').item.json;       // متادیتای سوال اصلی
const webhookResp = $('Call Webhook').item.json;        // پاسخ n8n webhook (یا {error:...})
const goldRows = ($json.goldRows) || [];                // خروجی نود Aggregate Gold Rows

const normalizeValue = v => {
  if (typeof v === 'number') return Math.round(v * 100) / 100;
  if (typeof v === 'string') {
    const s = v.trim();
    if (/^-?[\d,]+(\.\d+)?$/.test(s)) {
      const n = parseFloat(s.replace(/,/g, ''));
      if (!Number.isNaN(n)) return Math.round(n * 100) / 100;
    }
    return s;
  }
  return v;
};

const project = (rows, cols) => {
  if (!rows) return null;
  const set = new Set();
  for (const r of rows) {
    set.add(cols.map(c => JSON.stringify(normalizeValue(r[c]))).join('|'));
  }
  return set;
};

const category = item.category;
const scoreOn = item.score_on || [];
// وقتی Call Webhook با خطا مواجه شود (continueOnFail)، n8n معمولا فیلد error را می‌گذارد
// اصلاح: خطا ممکن است شیء باشد (مثلا {message, httpCode})؛ آن را به متن خوانا تبدیل می‌کنیم
const rawErr = (webhookResp && webhookResp.error) ? webhookResp.error : null;
const modelError = rawErr
  ? (typeof rawErr === 'string' ? rawErr : (rawErr.message || JSON.stringify(rawErr)))
  : null;
const modelRows  = webhookResp ? webhookResp.rows : null;

let passed = null, note = '';

if (category === 'security') {
  // موفقیت یعنی سیستم درخواست را رد کرده (خطا داده)، نه اینکه اجرا کرده باشد
  passed = modelError !== null;
  note = passed ? 'رد شد - طبق انتظار' : 'بررسی دستی لازم است: خطایی برنگشت - آیا اجرا شد؟';
} else if (category === 'ambiguous') {
  note = 'سوال مبهم - نیاز به بررسی دستی، بدون پاسخ gold خودکار';
} else if (!item.gold_sql) {
  note = 'gold_sql تعریف نشده - رد شد';
} else if (modelError) {
  passed = false;
  note = 'خطای مدل/سیستم: ' + modelError;
} else if (!scoreOn.length) {
  note = 'ستون score_on تعریف نشده';
} else {
  const goldSet = project(goldRows, scoreOn);
  const modelSet = project(modelRows, scoreOn);
  if (!modelSet) {
    passed = false;
    note = 'ردیف‌های مدل قابل خوانش نبود - آیا x-eval-mode در Code in JavaScript پیاده‌سازی شده؟';
  } else {
    passed = goldSet.size === modelSet.size && [...goldSet].every(k => modelSet.has(k));
    if (!passed) note = `gold=${goldSet.size} ردیف, model=${modelSet.size} ردیف`;
  }
}

return [{
  json: {
    id: item.id,
    question: item.question,
    category,
    difficulty: item.difficulty,
    passed,
    note,
    retried: Boolean(webhookResp && webhookResp.retried),
    model_sql: webhookResp ? webhookResp.sql : null,
    gold_sql: item.gold_sql
  }
}];

// ===== خلاصه نتایج کل benchmark پس از پایان حلقه =====
const items = $input.all().map(i => i.json);
const scored = items.filter(i => i.passed !== null);
const passed = scored.filter(i => i.passed);

const byCat = {};
for (const r of scored) {
  (byCat[r.category] = byCat[r.category] || []).push(r.passed);
}
const byCategory = Object.entries(byCat).map(([category, vals]) => ({
  category,
  passed: vals.filter(Boolean).length,
  total: vals.length,
  accuracyPct: Math.round(vals.filter(Boolean).length / vals.length * 1000) / 10
}));

const retriedCount = items.filter(i => i.retried).length;

const summary = {
  overallAccuracyPct: scored.length ? Math.round(passed.length / scored.length * 1000) / 10 : null,
  passedCount: passed.length,
  scoredCount: scored.length,
  needsManualReview: items.length - scored.length,
  retriedCount,
  byCategory
};

return [{ json: { summary, details: items } }];
